(function(){
'use strict';
var TRIP_MODE_DATA=[{"date":"10月·第1天","theme":"抵达后先读懂甘肃","summary":"抵达与安顿后，把下午留给甘肃省博物馆；傍晚沿黄河南岸看黄河母亲，晚餐坐下来吃一顿清真西北菜，不把第一天塞满。","time_range":"14:00–18:35","pace_label":"按时推进","stops":[{"place_id":"gansu-museum","name":"甘肃省博物馆","time":"14:00","dwell_minutes":180,"transport_mode":"地铁或出租车","transfer_minutes":35,"distance_km":6.0,"estimated_cost":"免费，需预约","practical_note":"从常设展优先看丝绸之路文明与彩陶，最后再进文创店；累了就跳过临展，别压缩闭馆前缓冲。","time_guard":"最晚16:00前入馆；若抵达兰州晚于14:30，改到第5天上午并直接去河岸。","map_query":"甘肃省博物馆 兰州市七里河区西津西路3号","map_url":"https://www.google.com/maps/search/?api=1&query=%E7%94%98%E8%82%83%E7%9C%81%E5%8D%9A%E7%89%A9%E9%A6%86+%E5%85%B0%E5%B7%9E%E5%B8%82%E4%B8%83%E9%87%8C%E6%B2%B3%E5%8C%BA%E8%A5%BF%E6%B4%A5%E8%A5%BF%E8%B7%AF3%E5%8F%B7","latitude":36.06672,"longitude":103.76878},{"place_id":"yellow-river-mother","name":"黄河母亲雕塑","time":"17:35","dwell_minutes":35,"transport_mode":"出租车后步行","transfer_minutes":20,"distance_km":3.4,"estimated_cost":"免费，车费约15—25元","practical_note":"从雕塑东南侧斜拍，让人物轮廓与河岸形成对角线；不要在主拍摄位久占。","time_guard":"18:15前离开，日落过早或风大时停留缩短到15分钟。","map_query":"黄河母亲雕塑 兰州市七里河区滨河路中段","map_url":"https://www.google.com/maps/search/?api=1&query=%E9%BB%84%E6%B2%B3%E6%AF%8D%E4%BA%B2%E9%9B%95%E5%A1%91+%E5%85%B0%E5%B7%9E%E5%B8%82%E4%B8%83%E9%87%8C%E6%B2%B3%E5%8C%BA%E6%BB%A8%E6%B2%B3%E8%B7%AF%E4%B8%AD%E6%AE%B5","latitude":36.05631,"longitude":103.79993},{"place_id":"rest-ma-laoliu-tongwei","name":"马老六清真餐饮·通渭路总店","time":"18:35","dwell_minutes":90,"transport_mode":"出租车","transfer_minutes":15,"distance_km":3.0,"estimated_cost":"两人约180—280元","practical_note":"两个人点一份手抓羊肉加一热一素即可，先问分量；三炮台可作为暖身饮品。","time_guard":"排队超过25分钟就改悦宾楼；21:00前结束，给第二天早起留睡眠。","map_query":"马老六清真餐饮 通渭路17号 兰州","map_url":"https://www.google.com/maps/search/?api=1&query=%E9%A9%AC%E8%80%81%E5%85%AD%E6%B8%85%E7%9C%9F%E9%A4%90%E9%A5%AE+%E9%80%9A%E6%B8%AD%E8%B7%AF17%E5%8F%B7+%E5%85%B0%E5%B7%9E","latitude":36.0578,"longitude":103.8252}],"shopping_advice":{"title":"第一天只做轻补给","description":"若缺围巾、润唇膏或饮水，只在住宿附近补齐；不带着行李绕路采购。","url":"https://www.google.com/maps/search/?api=1&query=%E5%BC%A0%E6%8E%96%E8%B7%AF%E6%AD%A5%E8%A1%8C%E8%A1%97%20%E5%85%B0%E5%B7%9E","link_label":"查看完整购物指南"},"photo_advice":{"title":"博物馆石色与黄河暮光","lighting":"室内避免玻璃反光，河岸在日落前约40分钟使用低角度侧光。","suitable_shots":["在博物馆入口台阶下用1×镜头保持立面端正","在黄河母亲东南侧以河岸斜线带出纵深"],"portrait_tip":"馆内先看禁拍标识；河岸人像站在主景侧边，不遮挡游客正面拍摄位。","shooting_plan":[{"time":"14:10","title":"甘肃省博物馆·对称立面","note":"站在广场中轴稍远处，手机保持胸口高度，用1×竖构图把台阶和馆名纳入。"},{"time":"17:45","title":"黄河母亲·暖色侧光","note":"摄影者向东侧退几步用2×轻压背景，被摄者沿雕塑边缘站立，注意不踩花坛。"}]}},{"date":"10月·第2天","theme":"木水车、白塔与铁桥","summary":"早餐先吃老字号牛肉面，随后沿黄河东段看水车；午休后慢上白塔山，傍晚下到中山桥，夜游船只作为天气合适时的可选收尾。","time_range":"07:40–17:20","pace_label":"按时推进","stops":[{"place_id":"rest-ma-zilu-dazhong","name":"马子禄牛肉面·大众巷店","time":"07:40","dwell_minutes":50,"transport_mode":"步行或地铁","transfer_minutes":20,"distance_km":2.0,"estimated_cost":"两人约40—80元","practical_note":"先买面票再选面型，两人可分别点二细和毛细对比；牛肉另点小份，不一次买大盘。","time_guard":"08:40必须离店；排队超过25分钟改再回首小吃并将牛肉面移到第5天。","map_query":"马子禄牛肉面 大众巷86号 兰州","map_url":"https://www.google.com/maps/search/?api=1&query=%E9%A9%AC%E5%AD%90%E7%A6%84%E7%89%9B%E8%82%89%E9%9D%A2+%E5%A4%A7%E4%BC%97%E5%B7%B786%E5%8F%B7+%E5%85%B0%E5%B7%9E","latitude":36.0622,"longitude":103.82},{"place_id":"waterwheel-park","name":"兰州水车博览园","time":"09:10","dwell_minutes":70,"transport_mode":"出租车","transfer_minutes":20,"distance_km":3.2,"estimated_cost":"免费，车费约15元","practical_note":"从靠河一侧看水车结构，再顺下游步行；若设备未运行，重点拍木构与现代城市的对比。","time_guard":"10:30前离开，风大或步道施工时缩短到40分钟。","map_query":"兰州水车博览园 城关区南滨河东路524号","map_url":"https://www.google.com/maps/search/?api=1&query=%E5%85%B0%E5%B7%9E%E6%B0%B4%E8%BD%A6%E5%8D%9A%E8%A7%88%E5%9B%AD+%E5%9F%8E%E5%85%B3%E5%8C%BA%E5%8D%97%E6%BB%A8%E6%B2%B3%E4%B8%9C%E8%B7%AF524%E5%8F%B7","latitude":36.06202,"longitude":103.83463},{"place_id":"baita-mountain","name":"白塔山公园与白塔寺","time":"14:20","dwell_minutes":150,"transport_mode":"出租车后步行","transfer_minutes":25,"distance_km":4.8,"estimated_cost":"公园免费；索道另计且须现场确认","practical_note":"先走低处寺院再决定是否继续上白塔；去程索道、回程步行可减少爬升，不在香客礼拜线上架三脚架。","time_guard":"16:50开始下山；若15:30仍未到中段观景位，就取消继续登高。","map_query":"白塔山公园 兰州市城关区白塔山1号","map_url":"https://www.google.com/maps/search/?api=1&query=%E7%99%BD%E5%A1%94%E5%B1%B1%E5%85%AC%E5%9B%AD+%E5%85%B0%E5%B7%9E%E5%B8%82%E5%9F%8E%E5%85%B3%E5%8C%BA%E7%99%BD%E5%A1%94%E5%B1%B11%E5%8F%B7","latitude":36.07102,"longitude":103.81544},{"place_id":"zhongshan-bridge","name":"中山桥","time":"17:20","dwell_minutes":70,"transport_mode":"步行下山","transfer_minutes":20,"distance_km":1.2,"estimated_cost":"免费","practical_note":"先在北端平台拍桥全景，再过桥拍钢架重复线条；桥面拥挤时把人像移到南岸步道。","time_guard":"18:40前结束主拍；若游船停航，直接沿南岸散步后返回。","map_query":"中山桥 兰州市城关区滨河路中段","map_url":"https://www.google.com/maps/search/?api=1&query=%E4%B8%AD%E5%B1%B1%E6%A1%A5+%E5%85%B0%E5%B7%9E%E5%B8%82%E5%9F%8E%E5%85%B3%E5%8C%BA%E6%BB%A8%E6%B2%B3%E8%B7%AF%E4%B8%AD%E6%AE%B5","latitude":36.06472,"longitude":103.81453}],"shopping_advice":{"title":"桥上不买大件","description":"今天路线以登山和摄影为主，只在桥南补水；伴手礼留到博物馆或张掖路集中买。","url":"https://www.google.com/maps/search/?api=1&query=%E5%BC%A0%E6%8E%96%E8%B7%AF%E6%AD%A5%E8%A1%8C%E8%A1%97%20%E5%85%B0%E5%B7%9E","link_label":"查看完整购物指南"},"photo_advice":{"title":"木水车到铁桥蓝调","lighting":"上午侧逆光勾勒木水车轮辐，日落后10—20分钟拍中山桥蓝调与灯光。","suitable_shots":["蹲低用水车轮辐框住对岸楼群","在北岸平台用2×镜头压缩中山桥与南岸城市"],"portrait_tip":"寺内避免对神像正面举机；桥面人像靠边快速完成，不阻塞通行。","shooting_plan":[{"time":"09:25","title":"水车博览园·轮辐框景","note":"站在水车斜侧并把手机降到腰部，用1×让轮辐包住人物，留意水边护栏。"},{"time":"16:15","title":"白塔山·河谷俯瞰","note":"在有护栏的观景位用2×拍铁桥和河道，被摄者侧身看河，避免翻越边界。"},{"time":"18:05","title":"中山桥·蓝调灯线","note":"从南岸用1×横构图保留倒影，轻点天空后下调曝光，等行人间隙再拍。"}]}},{"date":"10月·第3天","theme":"五泉清院与老城味道","summary":"上午只走五泉山核心古建，中午回老城吃包子并休息；下午看城隍庙与张掖路，晚饭选老字号悦宾楼，体力尚可再去正宁路分食两样。","time_range":"08:30–17:45","pace_label":"按时推进","stops":[{"place_id":"wuquanshan-park","name":"五泉山公园","time":"08:30","dwell_minutes":150,"transport_mode":"出租车","transfer_minutes":25,"distance_km":5.0,"estimated_cost":"公园通常免费，车费约20元","practical_note":"沿中轴看核心泉眼与庄严寺一带，先确认维修封闭区域；膝盖不适就原路下行，不走高处支线。","time_guard":"11:00下山，任何上坡支线以20分钟为限。